    [InlineData("func g<s/T, r/V>(m: s/T, n: r/V, x: s/i32, y: r/i32) -> i32\n    s is owner or ref\n    r is owner or ref\n    return g(n@move, m@move, y@move, x@move)\n", "clean")] // v01
