    [InlineData("struct Pr<s/T, U>\n    s is owner or ref\n    public init(x: s/T, y: s/U) => ()\nfunc use() -> i32\n    let a: i32 = 1\n    let b: i64 = 2\n    let p = Pr.init(a, b@ref)\n    return 0\n", "1*NoApplicableOverload_Kd")] // K3
